import{_ as s,C as r,o as d,c as p,j as e,a as t,E as i,a3 as l}from"./chunks/framework.D4-ViStF.js";const P=JSON.parse('{"title":"系辞上传","description":"《易传》之总纲——讲易之体用、圣人设卦观象系辞、大衍之数与天地之数，是进入易学思想的第一个入口。","frontmatter":{"title":"系辞上传","description":"《易传》之总纲——讲易之体用、圣人设卦观象系辞、大衍之数与天地之数，是进入易学思想的第一个入口。","category":"guide","aliases":["系辞上传","系辞上","系辞","xi ci zhuan shang"],"source":["《周易·系辞上传》"]},"headers":[],"relativePath":"yijing/shi-yi/xi-ci-zhuan-shang.md","filePath":"yijing/shi-yi/xi-ci-zhuan-shang.md","lastUpdated":1788140575000}'),u={name:"yijing/shi-yi/xi-ci-zhuan-shang.md"};function c(b,a,g,q,m,x){const n=r("DaoReadingPrelude"),o=r("DaoTextReading"),h=r("DaoKeywordCards");return d(),p("div",null,[a[0]||(a[0]=e("h1",{id:"系辞上传",tabindex:"-1"},[t("系辞上传 "),e("a",{class:"header-anchor",href:"#系辞上传","aria-label":'Permalink to "系辞上传"'},"​")],-1)),i(n,{title:"先通读全文，再顺着十七段的脉络读",summary:"《系辞上传》是十翼中最厚重的一篇，通论《易》之为书：从天尊地卑的宇宙生成，到易简之理、吉凶悔吝、大衍之数，再到一阴一阳之谓道与形上形下之分。全篇共十七段，层层推进，是进入易学思想的第一个入口。",points:[{label:"先读",text:"先把全文顺着读一遍，不逐字求解，抓大判断：易简、变通、生生、忧患。"},{label:"再辨",text:"留意天地、乾坤、圣人、君子、百姓——它们各自承担什么角色。"},{label:"后想",text:"最后回到具体章句（大衍之数、河洛之数）时，先知道它回答的是「筮法如何通于天」。"}],hint:"这篇虽长，内部结构很整：前段立宇宙论，中段论判断体系与君子之用，后段讲数与象，收束在德行。先读出整条脉络，再回到关键词与分段解读。"}),a[1]||(a[1]=l("",12)),i(o,{colophon:"天尊地卑 · 易简之理 · 生生之谓易 · 存乎德行",tone:"ink",sections:[{id:"duan-01",sentences:[["天尊地卑，乾坤定矣。"],["卑高以陈，贵贱位矣。"],["动静有常，刚柔断矣。"],["方以类聚，物以群分，吉凶生矣。"],["在天成象，在地成形，变化见矣。"],["是故刚柔相摩，八卦相荡，"],["鼓之以雷霆，润之以风雨；"],["日月运行，一寒一暑。"],["乾道成男，坤道成女。"]]},{id:"duan-02",sentences:[["乾知大始，坤作成物。"],["乾以易知，坤以简能；"],["易则易知，简则易从；"],["易知则有亲，易从则有功；"],["有亲则可久，有功则可大；"],["可久则贤人之德，可大则贤人之业。"],["易简而天下之理得矣。"],["天下之理得，而成位乎其中矣。"]]},{id:"duan-03",sentences:[["圣人设卦观象，系辞焉而明吉凶，刚柔相推而生变化。"],["是故吉凶者，失得之象也；"],["悔吝者，忧虞之象也；"],["变化者，进退之象也；"],["刚柔者，昼夜之象也。"],["六爻之动，三极之道也。"],["是故君子所居而安者，易之序也；"],["所乐而玩者，爻之辞也。"],["是故君子居则观其象而玩其辞，动则观其变而玩其占，是以自天祐之，吉无不利。"]]},{id:"duan-04",sentences:[["彖者，言乎象者也；"],["爻者，言乎变者也。"],["吉凶者，言乎其失得也；"],["悔吝者，言乎其小疵也。"],["无咎者，善补过者也。"],["是故列贵贱者存乎位，齐小大者存乎卦，"],["辩吉凶者存乎辞，忧悔吝者存乎介，震无咎者存乎悔。"],["是故卦有小大，辞有险易；辞也者，各指其所之。"]]},{id:"duan-05",sentences:[["易与天地准，故能弥纶天地之道。"],["仰以观于天文，俯以察于地理，是故知幽明之故；"],["原始反终，故知死生之说；"],["精气为物，游魂为变，是故知鬼神之情状。"],["与天地相似，故不违；"],["知周乎万物，而道济天下，故不过；"],["旁行而不流，乐天知命，故不忧；"],["安土敦乎仁，故能爱。"],["范围天地之化而不过，曲成万物而不遗，"],["通乎昼夜之道而知，故神无方而易无体。"]]},{id:"duan-06",sentences:[["一阴一阳之谓道，继之者善也，成之者性也。"],["仁者见之谓之仁，知者见之谓之知，百姓日用而不知，故君子之道鲜矣。"],["显诸仁，藏诸用，鼓万物而不与圣人同忧，盛德大业至矣哉！"],["富有之谓大业，日新之谓盛德。"],["生生之谓易，成象之谓乾，效法之谓坤，"],["极数知来之谓占，通变之谓事，阴阳不测之谓神。"]]},{id:"duan-07",sentences:[["夫易广矣大矣，以言乎远则不御，以言乎迩则静而正，以言乎天地之间则备矣。"],["夫乾，其静也专，其动也直，是以大生焉。"],["夫坤，其静也翕，其动也辟，是以广生焉。"],["广大配天地，变通配四时，"],["阴阳之义配日月，易简之善配至德。"]]},{id:"duan-08",sentences:[["子曰：“易，其至矣乎！"],["夫易，圣人所以崇德而广业也。"],["知崇礼卑，崇效天，卑法地。"],["天地设位，而易行乎其中矣。"],["成性存存，道义之门。”"]]},{id:"duan-09",sentences:[["圣人有以见天下之赜，而拟诸其形容，象其物宜，是故谓之象。"],["圣人有以见天下之动，而观其会通，以行其典礼，系辞焉以断其吉凶，是故谓之爻。"],["言天下之至赜而不可恶也。"],["言天下之至动而不可乱也。"],["拟之而后言，议之而后动，拟议以成其变化。"]]},{id:"duan-10",sentences:[["“鸣鹤在阴，其子和之。我有好爵，吾与尔靡之。”"],["子曰：“君子居其室，出其言善，则千里之外应之，况其迩者乎？"],["居其室，出其言不善，则千里之外违之，况其迩者乎？"],["言出乎身，加乎民；行发乎迩，见乎远。"],["言行，君子之枢机。"],["枢机之发，荣辱之主也。"],["言行，君子之所以动天地也，可不慎乎！”"]]},{id:"duan-11",sentences:[["“同人：先号咷而后笑。”"],["子曰：“君子之道，或出或处，或默或语。二人同心，其利断金。同心之言，其臭如兰。”"],["“初六，藉用白茅，无咎。”"],["子曰：“苟错诸地而可矣，藉之用茅，何咎之有？慎之至也。夫茅之为物薄，而用可重也。慎斯术也以往，其无所失矣。”"],["“劳谦，君子有终，吉。”"],["子曰：“劳而不伐，有功而不德，厚之至也。语以其功下人者也。德言盛，礼言恭；谦也者，致恭以存其位者也。”"],["“亢龙有悔。”"],["子曰：“贵而无位，高而无民，贤人在下位而无辅，是以动而有悔也。”"],["“不出户庭，无咎。”"],["子曰：“乱之所生也，则言语以为阶。君不密则失臣，臣不密则失身，几事不密则害成。是以君子慎密而不出也。”"],["子曰：“作易者，其知盗乎？易曰‘负且乘，致寇至。’"],["负也者，小人之事也。乘也者，君子之器也。"],["小人而乘君子之器，盗思夺之矣。上慢下暴，盗思伐之矣。"],["慢藏诲盗，冶容诲淫。"],["易曰：‘负且乘，致寇至。’盗之招也。”"]]},{id:"duan-12",sentences:[["大衍之数五十，其用四十有九。"],["分而为二以象两，挂一以象三，揲之以四以象四时，归奇于扐以象闰；"],["五岁再闰，故再扐而后挂。"],["天数五，地数五。"],["五位相得而各有合，天数二十有五，地数三十，凡天地之数五十有五，此所以成变化而行鬼神也。"],["乾之策二百一十有六，坤之策百四十有四，凡三百六十，当期之日。"],["二篇之策，万有一千五百二十，当万物之数也。"],["是故四营而成易，十有八变而成卦，八卦而小成。"],["引而伸之，触类而长之，天下之能事毕矣。"],["显道神德行，是故可与酬酢，可与祐神矣。"],["子曰：“知变化之道者，其知神之所为乎。”"]]},{id:"duan-13",sentences:[["易有圣人之道四焉：以言者尚其辞，以动者尚其变，以制器者尚其象，以卜筮者尚其占。"],["是以君子将有为也，将有行也，问焉而以言，其受命也如响。"],["无有远近幽深，遂知来物。非天下之至精，其孰能与于此。"],["参伍以变，错综其数。"],["通其变，遂成天下之文；极其数，遂定天下之象。非天下之至变，其孰能与于此。"],["易无思也，无为也，寂然不动，感而遂通天下之故。非天下之至神，其孰能与于此。"],["夫易，圣人之所以极深而研几也。"],["唯深也，故能通天下之志；唯几也，故能成天下之务；唯神也，故不疾而速，不行而至。"],["子曰：“易有圣人之道四焉”者，此之谓也。"]]},{id:"duan-14",sentences:[["天一，地二；天三，地四；天五，地六；天七，地八；天九，地十。"],["子曰：“夫易何为者也？夫易开物成务，冒天下之道，如斯而已者也。”"],["是故圣人以通天下之志，以定天下之业，以断天下之疑。"],["是故蓍之德圆而神，卦之德方以知，六爻之义易以贡。"],["圣人以此洗心，退藏于密，吉凶与民同患。"],["神以知来，知以藏往，其孰能与此哉！古之聪明睿知，神武而不杀者夫。"],["是以明于天之道，而察于民之故，是兴神物以前民用。"],["圣人以此斋戒，以神明其德夫。"],["是故阖户谓之坤，辟户谓之乾，一阖一辟谓之变，往来不穷谓之通，"],["见乃谓之象，形乃谓之器，制而用之谓之法，利用出入，民咸用之谓之神。"]]},{id:"duan-15",sentences:[["是故易有大极，是生两仪。两仪生四象。四象生八卦。"],["八卦定吉凶，吉凶生大业。"],["是故法象莫大乎天地；变通莫大乎四时；"],["县象著明莫大乎日月；崇高莫大乎富贵；"],["备物致用，立成器以为天下利，莫大乎圣人探赜索隐，钩深致远，以定天下之吉凶，成天下之亹亹者，莫大乎蓍龟。"],["是故天生神物，圣人则之；天地变化，圣人效之；"],["天垂象，见吉凶，圣人象之；河出图，洛出书，圣人则之。"]]},{id:"duan-16",sentences:[["易有四象，所以示也。系辞焉，所以告也；定之以吉凶，所以断也。"],["易曰：“自天祐之，吉无不利。”"],["子曰：“祐者，助也。天之所助者，顺也；人之所助者，信也。履信思乎顺，又以尚贤也。是以‘自天祐之，吉无不利’也。”"],["子曰：“书不尽言，言不尽意。”然则圣人之意，其不可见乎？"],["子曰：“圣人立象以尽意，设卦以尽情伪，系辞焉以尽其言。变而通之以尽利，鼓之舞之以尽神。”"],["乾坤，其易之缊邪？乾坤成列，而易立乎其中矣。"],["乾坤毁，则无以见易。易不可见，则乾坤或几乎息矣。"],["是故形而上者谓之道，形而下者谓之器。"],["化而裁之谓之变，推而行之谓之通，举而错之天下之民谓之事业。"]]},{id:"duan-17",sentences:[["是故夫象，圣人有以见天下之赜，而拟诸其形容，象其物宜，是故谓之象。"],["圣人有以见天下之动，而观其会通，以行其典礼，系辞焉以断其吉凶，是故谓之爻。"],["极天下之赜者存乎卦，鼓天下之动者存乎辞；"],["化而裁之存乎变；推而行之存乎通；"],["神而明之存乎其人；默而成之，不言而信，存乎德行。"]]}],"aria-label":"系辞上传原文"}),a[2]||(a[2]=e("blockquote",null,[e("p",null,"注：通行本多作「太极」，昇哥所用文本作「大极」，此处保留原文。下文「县象」之「县」通「悬」。")],-1)),a[3]||(a[3]=e("h2",{id:"【原典层】字词释义",tabindex:"-1"},[t("【原典层】字词释义 "),e("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(h,{title:"字词释义",items:[{term:"乾",pinyin:["qián"],meaning:"阳、天、创始之力。「乾知大始」——乾主导开始，是方向、是意志、是那个「第一动」；「成象之谓乾」，乾的功能是成就形象。"},{term:"坤",pinyin:["kūn"],meaning:"阴、地、成物之力。「坤作成物」——坤负责完成与落地，把乾的方向变成具体的物；「效法之谓坤」，坤的功能是承接效法。"},{term:"易",pinyin:["yì"],meaning:"三义并包：变易（阴阳往来）、简易（易则易知）、不易（常理）。“生生之谓易”——不断地生、生了又生，才是《易》最核心的定义。"},{term:"简",pinyin:["jiǎn"],meaning:"简约、朴素。「坤以简能」——坤的方式是简，踏实、不花巧；执行最需要的是稳定与可重复。易与简之别：易是认知层面的透明，简是操作层面的可靠。"},{term:"象",pinyin:["xiàng"],meaning:"圣人见天下之赜，拟诸其形容、象其物宜而立的象。「见乃谓之象」——可被看见、可被感知的征象。象是先于辞的，言说不尽处，由象来显意。"},{term:"爻",pinyin:["yáo"],meaning:"「爻者，言乎变者也」——爻讲的是每一爻的变动与具体情境；「六爻之义易以贡」，六爻最具体地呈现时位与变化。"},{term:"彖",pinyin:["tuàn"],meaning:"「彖者，言乎象者也」——彖辞说整卦的形象与整体义理，是静态的一卦之断。"},{term:"吉凶",pinyin:["jí","xiōng"],meaning:"「吉凶者，失得之象也」——吉凶是得失判断，不是道德好坏判断；「八卦定吉凶，吉凶生大业」，看清吉凶而适当行动，才有大业。"},{term:"悔吝",pinyin:["huǐ","lìn"],meaning:"「悔吝者，忧虞之象也」「言乎其小疵也」——小毛病、还未酿成大错的预警；「忧悔吝者存乎介」，要在细微的关键节点上警觉。"},{term:"无咎",pinyin:["wú","jiù"],meaning:"「无咎者，善补过者也」——不是「没有错」，而是有错但善于补救；「震无咎者存乎悔」——无咎来自主动的悔悟与震动。"},{term:"弥纶",pinyin:["mí","lún"],meaning:"弥是充满，纶是贯穿。「弥纶天地之道」——《易》充满并贯穿天地的一切道理，没有遗漏。"},{term:"生生",pinyin:["shēng","shēng"],meaning:"「生生之谓易」——不断地生、生了又生。变化可以是破坏性的，生生是创造性的；每一次变化都是新生命的诞生。"},{term:"大衍",pinyin:["dà","yǎn"],meaning:"大衍之数五十，其用四十有九。大衍是演算天地变化的数；五十为太极之体，不动不用；四十九为大衍之用，动而演化。"},{term:"揲",pinyin:["shé"],meaning:"「揲之以四以象四时」——每四根蓍草一组地数，象春夏秋冬四时；是筮法「四营」之一。"},{term:"挂一",pinyin:["guà","yī"],meaning:"「挂一以象三」——从右堆取一根蓍草挂于指间，象天、地、人三才。"},{term:"策",pinyin:["cè"],meaning:"蓍草之数。《乾》之策二百一十有六，《坤》之策百四十有四，合三百六十，当期之日；二篇之策万有一千五百二十，当万物之数。"},{term:"太极（大极）",pinyin:["tài","jí"],meaning:"「《易》有大极，是生两仪」——万有未分而含具一切变化的根源，不是物体，是变化的根。通行本多作「太极」。"},{term:"两仪",pinyin:["liǎng","yí"],meaning:"阴与阳。不是对立而是相待：无阖辟无所从出，无辟阖不能成用；两仪一发生，变化就有了最基本的动力。"},{term:"四象",pinyin:["sì","xiàng"],meaning:"阴阳消长的四种状态：少阳、老阳、少阴、老阴。四象说的不是两个静态标签，而是阴阳的时序与程度——盛不可恃，穷不可绝。"},{term:"道",pinyin:["dào"],meaning:"「形而上者谓之道」——贯通万物的原理、秩序与方向；「一阴一阳之谓道」——道不是静止的，是阴阳之间那个永恒的来回。"},{term:"器",pinyin:["qì"],meaning:"「形而下者谓之器」——已成形、可见、可操作的具体事物与方法制度。道必须通过器显现，器必须依道才不失正用。"},{term:"神",pinyin:["shén"],meaning:"「阴阳不测之谓神」——神不是鬼神，是阴阳变化中那个不可完全测度的部分；「神无方」——神妙没有固定方位，无处不在。"},{term:"几",pinyin:["jī"],meaning:"「极深而研几」——研究最细微、最初起、尚未完全显露的机兆。「唯几也，故能成天下之务」——在事机初起时把握关键。"},{term:"赜",pinyin:["zé"],meaning:"「天下之赜」——幽深复杂、难以言说的复杂。「极天下之赜者存乎卦」——卦把最复杂的情状凝聚为可观之象。"},{term:"洗心",pinyin:["xǐ","xīn"],meaning:"「圣人以此洗心」——洗去私欲、成见、急于求答案的躁动；心能静、能诚、能不强求，象与辞才可能如其所是地显现。"},{term:"阖辟",pinyin:["hé","bì"],meaning:"「阖户谓之坤，辟户谓之乾」——关门收合象坤，开门开展象乾；一阖一辟谓之变，往来不穷谓之通。"},{term:"存存",pinyin:["cún","cún"],meaning:"「成性存存，道义之门」——成性不是一次就够，成了之后还要存，存了还要存；德是每天都要维护的状态。"}]}),a[4]||(a[4]=l("",307))])}const k=s(u,[["render",c]]);export{P as __pageData,k as default};
